CREATE DATABASE IF NOT EXISTS abc_school CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE abc_school;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,user_id VARCHAR(50) UNIQUE,password VARCHAR(255),name VARCHAR(150),role ENUM('admin','principal','teacher'),email VARCHAR(150),phone VARCHAR(30),status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS school_settings(id INT PRIMARY KEY,school_name VARCHAR(200),board VARCHAR(100),affiliation_number VARCHAR(100),school_code VARCHAR(100),academic_session VARCHAR(30),principal_name VARCHAR(150),vice_principal_name VARCHAR(150),address TEXT,city VARCHAR(100),state VARCHAR(100),pin_code VARCHAR(10),phone VARCHAR(30),email VARCHAR(150));
CREATE TABLE IF NOT EXISTS classes(id INT AUTO_INCREMENT PRIMARY KEY,class_name VARCHAR(50) UNIQUE,display_order INT);
CREATE TABLE IF NOT EXISTS sections(id INT AUTO_INCREMENT PRIMARY KEY,class_id INT,section_name VARCHAR(20),UNIQUE(class_id,section_name));
CREATE TABLE IF NOT EXISTS subjects(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),code VARCHAR(50),max_marks DECIMAL(10,2) DEFAULT 100);
CREATE TABLE IF NOT EXISTS teacher_assignments(id INT AUTO_INCREMENT PRIMARY KEY,teacher_id INT,class_id INT,section_id INT,subject_id INT,academic_session VARCHAR(30));
CREATE TABLE IF NOT EXISTS students(id INT AUTO_INCREMENT PRIMARY KEY,admission_number VARCHAR(30) UNIQUE,student_name VARCHAR(150),father_name VARCHAR(150),mother_name VARCHAR(150),dob DATE,gender VARCHAR(20),photo LONGTEXT,address TEXT,mobile VARCHAR(20),email VARCHAR(150),academic_session VARCHAR(30),class_name VARCHAR(50),section VARCHAR(20),roll_number VARCHAR(50),status VARCHAR(20) DEFAULT 'active',admission_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS exams(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),academic_session VARCHAR(30),start_date DATE,end_date DATE,published TINYINT DEFAULT 0,created_by INT);
CREATE TABLE IF NOT EXISTS exam_subjects(id INT AUTO_INCREMENT PRIMARY KEY,exam_id INT,subject_id INT,max_marks DECIMAL(10,2) DEFAULT 100,passing_marks DECIMAL(10,2) DEFAULT 33);
CREATE TABLE IF NOT EXISTS marks(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,exam_id INT,subject_id INT,obtained_marks DECIMAL(10,2),entered_by INT,UNIQUE(student_id,exam_id,subject_id));
CREATE TABLE IF NOT EXISTS attendance(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT,subject_id INT,teacher_id INT,attendance_date DATE,status VARCHAR(20),remarks VARCHAR(255),UNIQUE(student_id,subject_id,attendance_date));
CREATE TABLE IF NOT EXISTS fee_payments(id INT AUTO_INCREMENT PRIMARY KEY,receipt_number VARCHAR(30) UNIQUE,student_id INT,amount_paid DECIMAL(10,2),payment_period VARCHAR(50),payment_date DATE,payment_mode VARCHAR(30),collected_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notices(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255),description TEXT,published TINYINT DEFAULT 0,publish_date DATETIME,created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
